    "what_toolbar_icon_and": "ツールバーのアイコンと Alt+S で開くもの: 固定はアイコンの下のポップアップ、独立ウィンドウは電卓のサイズに合わせて大きさが変わる専用ウィンドウ、上級は大きなウィンドウに電卓を開き、その横にツールが並ぶモードで、元に戻すと独立ウィンドウモードで開きます。「開く」を押すと、選んだモードで開きます。独立ウィンドウモードと上級モードはツールバーアイコンのメニューにもあり、独立ウィンドウモードはページ上のボタンからも開けます。",
