    "turned_off_on": "オフにしたサイト:",
    "choose_how_numbers_look": "数値の表示方法を選びます。結果を固定小数点で丸める、指数表記（1.23e+4）、工学表記（12.3e+3）のほか、桁区切りと小数点の書き方も選べます。「自動」の桁数では、各結果に必要なだけの桁を表示します。",
    "notation": "表記",
