    "number_to_whole_number": "にあります。数を、それ以下または以上の整数に、また最も近い整数（0 から遠い方へ）にします。これらと、0 の方向へ丸める trunc は、貼り付けても使えます: floor(7.5) = 7。",
    "logarithm_to_any_base_2": "（任意の底の対数: 8 log",
