    "again_to_return_buttons": "をもう一度クリックすると、ボタンが元の機能に戻ります。",
    "opens_parenthetical_expression_expressions": "[(] かっこで囲まれた式を開きます。式はネストできます。クリックするとボタンの周りに輪が表示され、かっこの式がまだ開いていること（すべてが閉じかっこまたは等号で閉じられるまで）を示します。",
    "number_right_before_parenthesis": "かっこの直前の数値は掛け算になります: 5 ( 2 + 3 ) は 5 × (2 + 3) です。",
    "closes_parenthetical_expression_ring": "[)] かっこで囲まれた式を閉じます。( キーの周りの輪は、すべての式がこのキーまたは等号で閉じられるまで残ります。",
    "calculates_percentages_adds_markups": "[%] パーセントを計算し、マークアップを加え、割引を引きます。単独では値を 100 で割ります: 50 % は 0.5 を返します。たとえば 500 の 8% を計算するには、8 % × 500 = と入力すると 40 が返ります。",
    "to_add_markup_or": "マークアップを加えたり割引を引いたりするには、+ または – キーの後で使います。たとえば、消費税 8% の 500 ドルの品物の合計金額を計算するには、500 + 8 % = と入力すると 540 が返ります。",
