    "since_only_few_atoms_4": "レントゲニウムはごくわずかな原子しか作られたことがないため、現在、基礎的な科学研究以外の用途はありません。",
    "roentgenium_was_first_produced": "レントゲニウムは、1994 年の終わりごろ、ドイツのダルムシュタットにある重イオン研究所で、ペーター・アルムブルスター、ゴットフリート・ミュンツェンベルクとそのチームが初めて作りました。",
