    "since_only_few_atoms_5": "コペルニシウムはごくわずかな原子しか作られたことがないため、現在、基礎的な科学研究以外の用途はありません。",
    "copernicium_was_first_produced": "コペルニシウムは、1996 年 2 月 9 日にドイツのダルムシュタットにある重イオン研究所で、ペーター・アルムブルスター、ゴットフリート・ミュンツェンベルクとそのチームが初めて作りました。",
