    "since_only_few_atoms_9": "リバモリウムはごくわずかな原子しか作られたことがないため、現在、基礎的な科学研究以外の用途はありません。",
    "on_december_6_2000": "2000 年 12 月 6 日、ロシアのドゥブナにある合同原子核研究所の科学者が、米国エネルギー省ローレンス・リバモア国立研究所の科学者とともに、リバモリウムの生成を発表しました。",
